// @generated by:gauntlet run:g-o-d-s-e-y-e-control-client
import { randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION, ProjectResponse } from "@godseye/contracts";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createControlClient } from "../packages/control-client/src/index.js";
import { projectInput, repository } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("private first-party control client", () => {
  let fixture: OwnerAuthFixture;
  let headers: Headers;
  let transport: typeof fetch;

  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    headers = (await fixture.session()).headers;
    transport = async (input, init) => fixture.app.request(new Request(input, init));
  });
  afterEach(async () => {
    await fixture.close();
  });

  function client(fetcher = transport, requestHeaders: HeadersInit = headers) {
    return createControlClient({
      baseUrl: `${fixture.origin}/api/v1`,
      fetch: fetcher,
      headers: requestHeaders,
    });
  }

  it("T33 T37 creates, reads, lists and binds a repository through actual authenticated HTTP with safe replay", async () => {
    const control = client();
    const createKey = randomUUID();
    const created = ProjectResponse.parse(await control.createProject(projectInput, createKey));
    expect(await control.createProject(projectInput, createKey)).toEqual(created);
    expect(await control.getProject(created.id)).toEqual(created);
    expect(await control.listProjects()).toEqual([created]);
    const binding = { repository, expectedRevision: created.revision };
    const bindingKey = randomUUID();
    const saved = ProjectResponse.parse(
      await control.configureRepository(created.id, binding, bindingKey),
    );
    expect(saved.repository).toEqual(repository);
    expect(await control.configureRepository(created.id, binding, bindingKey)).toEqual(saved);
    expect(await control.getProject(created.id)).toEqual(saved);
    await expect(
      control.createProject({ ...projectInput, slug: "conflicting-replay" }, createKey),
    ).rejects.toMatchObject({
      name: "ControlHttpError",
      status: 409,
      code: "IDEMPOTENCY_CONFLICT",
    });
    expect(await control.listProjects()).toHaveLength(1);
  });

  it("T37 refuses a write without its required idempotency key and makes no project", async () => {
    const control = client();
    await expect(control.createProject(projectInput, "")).rejects.toThrow(/idempotency/i);
    expect(await control.listProjects()).toEqual([]);
  });

  it("T-AC-01 exposes a typed authentication failure instead of treating it as project data", async () => {
    await expect(client(transport, fixture.headers()).listProjects()).rejects.toMatchObject({
      name: "ControlHttpError",
      status: 401,
      code: "UNAUTHENTICATED",
    });
  });

  it("T34 fails visibly when a project response gains an unrecognized authority field", async () => {
    const created = ProjectResponse.parse(await client().createProject(projectInput, randomUUID()));
    const malformed: typeof fetch = async (input, init) => {
      const response = await transport(input, init);
      const body = await response.json();
      return Response.json(
        { ...body, ownerRole: "root" },
        { status: response.status, headers: response.headers },
      );
    };
    await expect(client(malformed).getProject(created.id)).rejects.toMatchObject({
      name: "ControlContractError",
      code: "INVALID_RESPONSE",
    });
  });

  it.each([null, "999.0.0"])(
    "T34 refuses a successful HTTP response with incompatible contract version %s",
    async (version) => {
      const incompatible: typeof fetch = async (input, init) => {
        const response = await transport(input, init);
        const responseHeaders = new Headers(response.headers);
        if (version === null) responseHeaders.delete(CONTROL_API_HEADER);
        else responseHeaders.set(CONTROL_API_HEADER, version);
        return new Response(await response.text(), {
          status: response.status,
          headers: responseHeaders,
        });
      };
      expect(CONTROL_API_VERSION).not.toBe(version);
      await expect(client(incompatible).listProjects()).rejects.toMatchObject({
        name: "ControlContractError",
        code: "UNSUPPORTED_VERSION",
      });
    },
  );
});
